def research_turn(client, question, search_tool):
    hits = search_tool.run(question)
    system = BASE_PROMPT + "\n\nLatest search results:\n" + "\n".join(h["snippet"] for h in hits)
    return client.messages.create(model=MODEL, max_tokens=600, system=system,
                                  messages=[{"role": "user", "content": question}])

def load_plugin_tools(manifest_upload):
    manifest = json.load(manifest_upload)
    return [{"type": "function", "function": {
                "name": t["name"],
                "description": t["description_for_model"],
                "parameters": t["parameters"]}}
            for t in manifest["tools"]]

def plugin_chat(client, manifest_upload, q):
    return client.chat.completions.create(model=MODEL, max_tokens=400,
        tools=load_plugin_tools(manifest_upload), messages=[{"role": "user", "content": q}])

