from concurrent.futures import ThreadPoolExecutor

def summarise_all(client, documents):
    def one(doc):
        return client.chat.completions.create(model=MODEL, max_tokens=200,
            messages=[{"role": "user", "content": doc}]).choices[0].message.content
    with ThreadPoolExecutor(max_workers=len(documents)) as pool:
        return list(pool.map(one, documents))

