MAX_DEPTH = 2

def run_agent(client, task, depth=0):
    out = client.messages.create(model=MODEL, max_tokens=800, tools=[DELEGATE_TOOL],
        messages=[{"role": "user", "content": task}])
    if depth >= MAX_DEPTH:
        return out
    for b in out.content:
        if b.type == "tool_use" and b.name == "delegate":
            for subtask in b.input["subtasks"][:3]:
                run_agent(client, subtask, depth + 1)
    return out

